import { EventEmitter, once } from 'node:events';

class Kasir extends EventEmitter {
  #total = 0;
  bayar(jumlah) {
    if (jumlah <= 0) {
      this.emit('error', new Error(`Jumlah tidak valid: ${jumlah}`));
      return;
    }
    this.#total += jumlah;
    this.emit('bayar', jumlah, this.#total);
  }
}
const kasir = new Kasir();
kasir.on('bayar', (j, t) => console.log(`+${j} (total ${t})`));
kasir.on('error', (e) => console.log('Ditolak:', e.message));

kasir.bayar(18000);
kasir.bayar(-5);
setTimeout(() => kasir.bayar(12000), 10);
const [jumlah, total] = await once(kasir, 'bayar');
console.log('Ditunggu:', jumlah, total);

