import { EventEmitter } from 'node:events';
class Timbangan extends EventEmitter {
  timbang(gram) {
    if (gram > 1000) this.emit('berat', gram);
  }
}
const t = new Timbangan();
t.on('berat', (g) => console.log(`Berat: ${g}`));
t.timbang(500);
t.timbang(1500);
